import { useEffect, useState } from "react";
import { Zap } from "lucide-react";

const SSWX_LOGO = "data:image/png;base64,";

interface Props {
  onDone: () => void;
}

export default function SplashScreen({ onDone }: Props) {
  const [phase, setPhase] = useState<"loading" | "fade">("loading");

  useEffect(() => {
    const t1 = setTimeout(() => setPhase("fade"), 1800);
    const t2 = setTimeout(() => onDone(), 2400);
    return () => { clearTimeout(t1); clearTimeout(t2); }
  }, [onDone]);

  return (
    <>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Cinzel+Decorative:wght@700;900&family=Rajdhani:wght@500;600;700&family=Dancing+Script:wght@700&family=Great+Vibes&family=Orbitron:wght@700;900&display=swap');

        @keyframes bounce {
          0%, 100% { transform: translateY(0); opacity: 0.4; }
          50% { transform: translateY(-6px); opacity: 1; }
        }
        @keyframes splashFadeIn {
          from { opacity: 0; transform: translateY(18px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes logoGlow {
          0%, 100% { box-shadow: 0 0 60px hsl(262 75% 62% / 0.4), 0 0 120px hsl(262 75% 62% / 0.15); }
          50% { box-shadow: 0 0 80px hsl(262 75% 62% / 0.7), 0 0 160px hsl(262 75% 62% / 0.3); }
        }
        @keyframes lightningFlash {
          0%, 92%, 100% { opacity: 0; }
          93%, 95% { opacity: 0.08; }
          94%, 96% { opacity: 0; }
          97%, 99% { opacity: 0.05; }
        }
        @keyframes scanline {
          0% { transform: translateY(-100%); }
          100% { transform: translateY(100vh); }
        }
        @keyframes nameGlowPulse {
          0%, 100% { filter: brightness(1); }
          50% { filter: brightness(1.4); }
        }

        .splash-title {
          font-family: 'Cinzel Decorative', serif;
          font-weight: 900;
          font-size: 2.8rem;
          letter-spacing: 0.15em;
          text-transform: uppercase;
          background: linear-gradient(135deg, #c4b5fd 0%, #a78bfa 40%, #7c3aed 70%, #c4b5fd 100%);
          -webkit-background-clip: text;
          -webkit-text-fill-color: transparent;
          background-clip: text;
          text-shadow: none;
          filter: drop-shadow(0 0 20px hsl(262 75% 62% / 0.7)) drop-shadow(0 0 40px hsl(262 75% 62% / 0.4));
          animation: splashFadeIn 0.8s ease forwards;
          animation-delay: 0.3s;
          opacity: 0;
        }
        .splash-subtitle {
          font-family: 'Rajdhani', sans-serif;
          font-weight: 600;
          letter-spacing: 0.45em;
          font-size: 0.72rem;
          text-transform: uppercase;
          color: hsl(262 40% 72%);
          animation: splashFadeIn 0.8s ease forwards;
          animation-delay: 0.6s;
          opacity: 0;
        }
        .splash-tagline {
          font-family: 'Rajdhani', sans-serif;
          font-weight: 500;
          letter-spacing: 0.3em;
          font-size: 0.62rem;
          text-transform: uppercase;
          color: hsl(262 30% 55%);
          animation: splashFadeIn 0.8s ease forwards;
          animation-delay: 0.9s;
          opacity: 0;
        }
        .sswx-logo {
          animation: splashFadeIn 0.8s ease forwards;
          animation-delay: 0.15s;
          opacity: 0;
          filter: drop-shadow(0 0 10px hsl(262 75% 62% / 0.35));
        }
        .corner-meta {
          font-family: 'Rajdhani', sans-serif;
          font-weight: 500;
          font-size: 0.58rem;
          letter-spacing: 0.12em;
          text-transform: uppercase;
          color: hsl(262 20% 45%);
          line-height: 1.6;
          animation: splashFadeIn 0.8s ease forwards;
          animation-delay: 1.2s;
          opacity: 0;
        }
        .jay-print {
          font-family: 'Orbitron', sans-serif;
          font-weight: 700;
          font-size: 0.8rem;
          color: #ccccff;
          text-shadow: 0 0 8px #ccccff, 0 0 20px #aaaaff, 0 0 40px #8888ff;
          letter-spacing: 0.08em;
          animation: nameGlowPulse 2.5s ease-in-out infinite;
        }
        .jay-cursive {
          font-family: 'Great Vibes', cursive;
          font-size: 1.3rem;
          color: #ccccff;
          text-shadow: 0 0 8px #ccccff, 0 0 22px #aaaaff, 0 0 45px #8888ff;
          line-height: 1.1;
          animation: nameGlowPulse 2.5s ease-in-out 0.3s infinite;
        }
        .keaton-print {
          font-family: 'Orbitron', sans-serif;
          font-weight: 700;
          font-size: 0.8rem;
          color: #89CFF0;
          text-shadow: 0 0 8px #89CFF0, 0 0 20px #5bb8e8, 0 0 40px #3a9dd4;
          letter-spacing: 0.08em;
          animation: nameGlowPulse 2.5s ease-in-out 0.5s infinite;
        }
        .keaton-cursive {
          font-family: 'Dancing Script', cursive;
          font-size: 1.3rem;
          color: #89CFF0;
          text-shadow: 0 0 8px #89CFF0, 0 0 22px #5bb8e8, 0 0 45px #3a9dd4;
          line-height: 1.1;
          animation: nameGlowPulse 2.5s ease-in-out 0.8s infinite;
        }
        .credits-label {
          font-family: 'Rajdhani', sans-serif;
          font-weight: 600;
          font-size: 0.6rem;
          letter-spacing: 0.18em;
          text-transform: uppercase;
          color: hsl(262 25% 52%);
          margin-bottom: 4px;
        }
        .ampersand-sep {
          font-family: 'Cinzel Decorative', serif;
          font-size: 0.7rem;
          color: hsl(262 40% 55%);
          margin: 2px 0;
          text-shadow: 0 0 10px hsl(262 75% 62% / 0.4);
        }
        .corner-credits {
          animation: splashFadeIn 0.8s ease forwards;
          animation-delay: 1.4s;
          opacity: 0;
        }
      `}</style>

      <div
        className="fixed inset-0 z-[999] flex flex-col items-center justify-center overflow-hidden"
        style={{
          background: "radial-gradient(ellipse at 50% 30%, hsl(262 40% 12%) 0%, hsl(232 22% 5%) 60%, hsl(232 25% 3%) 100%)",
          transition: "opacity 0.8s ease",
          opacity: phase === "fade" ? 0 : 1,
          pointerEvents: phase === "fade" ? "none" : "auto",
        }}
      >
        {/* Atmospheric lightning flash overlay */}
        <div
          className="absolute inset-0 pointer-events-none"
          style={{
            background: "hsl(262 90% 95%)",
            animation: "lightningFlash 4s ease-in-out 1.5s infinite",
          }}
        />

        {/* Subtle scanline effect */}
        <div
          className="absolute inset-0 pointer-events-none overflow-hidden"
          style={{ opacity: 0.04 }}
        >
          <div
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              right: 0,
              height: "2px",
              background: "linear-gradient(transparent, hsl(262 75% 62%), transparent)",
              animation: "scanline 6s linear 2s infinite",
            }}
          />
        </div>

        {/* Top gradient vignette */}
        <div
          className="absolute top-0 left-0 right-0 h-32 pointer-events-none"
          style={{ background: "linear-gradient(to bottom, hsl(262 40% 8% / 0.6), transparent)" }}
        />

        {/* Bottom gradient vignette */}
        <div
          className="absolute bottom-0 left-0 right-0 h-32 pointer-events-none"
          style={{ background: "linear-gradient(to top, hsl(232 25% 3% / 0.8), transparent)" }}
        />

        {/* SSWX Official Logo - top */}
        <div className="sswx-logo absolute top-6 left-1/2 -translate-x-1/2">
          <img
            src={SSWX_LOGO}
            alt="SSWX Official"
            style={{ height: "52px", width: "auto", objectFit: "contain" }}
          />
        </div>

        {/* Main content */}
        <div className="relative flex flex-col items-center gap-5 px-4">

          {/* Logo icon */}
          <div className="relative" style={{ animation: "splashFadeIn 0.8s ease forwards", opacity: 0 }}>
            <div
              className="w-24 h-24 rounded-2xl border-2 border-primary/40 flex items-center justify-center"
              style={{
                background: "linear-gradient(135deg, hsl(262 60% 15%) 0%, hsl(232 30% 10%) 100%)",
                animation: "logoGlow 2.5s ease-in-out infinite",
              }}
            >
              <Zap className="w-12 h-12 text-primary" fill="currentColor" />
            </div>
            <div
              className="absolute inset-0 rounded-2xl"
              style={{
                background: "radial-gradient(circle at 50% 50%, hsl(262 75% 62% / 0.15) 0%, transparent 70%)",
                animation: "pulse 2s ease-in-out infinite",
              }}
            />
          </div>

          {/* Title */}
          <div className="text-center" style={{ marginTop: "-4px" }}>
            <div className="splash-title">StormSync</div>
            <div className="splash-subtitle mt-1">Forecasts &amp; Alerts Dashboard</div>
            <div className="splash-tagline mt-1.5">Open-Meteo · NWS · SPC · SWPC</div>
          </div>

          {/* Loading dots */}
          <div className="flex items-center gap-1.5 mt-1">
            {[0, 1, 2].map((i) => (
              <div
                key={i}
                className="w-1.5 h-1.5 rounded-full bg-primary"
                style={{
                  animation: `bounce 1.2s ease-in-out ${i * 0.2}s infinite`,
                  opacity: 0.7,
                }}
              />
            ))}
          </div>
        </div>

        {/* ── BOTTOM-LEFT CORNER: Credits ── */}
        <div
          className="corner-credits absolute bottom-5 left-5 flex flex-col items-start"
          style={{ maxWidth: "220px" }}
        >
          <div className="credits-label">Created &amp; Developed By:</div>

          {/* Jay Myers */}
          <div className="jay-print">Jay Myers</div>
          <div className="jay-cursive">(Jeremy J Myers)</div>

          <div className="ampersand-sep">&amp;</div>

          {/* Keaton Preston */}
          <div className="keaton-print">Keaton Preston</div>
          <div className="keaton-cursive">Keaton Preston</div>
        </div>

        {/* ── BOTTOM-RIGHT CORNER: Metadata ── */}
        <div className="corner-meta absolute bottom-5 right-5 text-right">
          <div style={{ color: "hsl(262 35% 60%)", fontWeight: 600, fontSize: "0.62rem", letterSpacing: "0.15em" }}>
            Circa &apos;2026
          </div>
          <div>Created On: May 11, 2026</div>
          <div>Updated On: May 16, 2026</div>
          <div style={{ marginTop: "4px", color: "hsl(262 15% 38%)" }}>
            &copy; 2026 StormSync Media. All Rights Reserved.
          </div>
        </div>
      </div>
    </>
  );
}
